}

.routine-planner-avatars .routine-planner-avatar + .routine-planner-avatar {
  @apply [margin-left:calc(var(--johnbot-space-1-5)_*_-1)];
}

.routine-planner-run.ui-button {
  @apply [display:grid];
  @apply [width:100%];
  @apply [height:auto];
  @apply [min-height:var(--johnbot-control-sm)];
  @apply [grid-template-columns:auto_minmax(0,_1fr)_auto];
  grid-template-areas:
    "mark time avatars"
    "name name name";
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-0-5)_var(--johnbot-space-1)];
  @apply [border-radius:var(--johnbot-radius-sm)];
  @apply [background:var(--johnbot-bg-control)];
  @apply [padding:var(--johnbot-space-1)_var(--johnbot-space-1-5)];
  @apply [text-align:left];
  @apply [font-size:var(--johnbot-text-sm)];
}

.routine-planner-run .routine-planner-status {
  @apply [grid-area:mark];
}

.routine-planner-run-time {
  @apply [grid-area:time];
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-variant-numeric:tabular-nums];
}

/* Two lines before an ellipsis: a day column is narrow, and the name is what tells runs apart. */
.routine-planner-run-name {
  @apply [display:-webkit-box];
  @apply [grid-area:name];
  @apply [min-width:0];
  @apply [overflow:hidden];
  @apply [-webkit-box-orient:vertical];
  @apply [-webkit-line-clamp:2];
  @apply [line-height:1.3];
  @apply [overflow-wrap:break-word];
  @apply [white-space:normal];
}

.routine-planner-run .routine-planner-avatars {
  @apply [grid-area:avatars];
}

/* A paused run would happen if the routine resumed. It keeps its place but loses its weight. */
.routine-planner-run[data-status="paused"],
.routine-planner-entry[data-status="paused"] {
