}

.routine-planner-run[data-status="paused"] {
  @apply [outline:1px_dashed_var(--johnbot-border-grouped)];
  @apply [outline-offset:-1px];
  @apply [background:var(--johnbot-transparent)];
}

.routine-planner-run[data-status="failed"] {
  @apply [background:var(--johnbot-danger-soft)];
}

.routine-planner-run[data-status="completed"] .routine-planner-run-name {
  @apply [color:var(--johnbot-text-muted)];
}

.routine-planner-more.ui-button {
  @apply [justify-self:start];
  @apply [color:var(--johnbot-text-muted)];
}

/* A month has up to six rows of days: a run is one line, and the column heads name the weekdays. */
.routine-planner[data-view="month"] .routine-planner-day {
  @apply [min-height:7rem];
}

.routine-planner[data-view="month"] .routine-planner-day-button > span {
  @apply [display:none];
}

.routine-planner[data-view="month"] .routine-planner-run.ui-button {
  @apply [grid-template-columns:auto_auto_minmax(0,_1fr)];
  grid-template-areas: "mark time name";
}

.routine-planner[data-view="month"] .routine-planner-run-name {
  @apply [display:block];
  @apply [overflow:hidden];
  @apply [text-overflow:ellipsis];
  @apply [white-space:nowrap];
}

.routine-planner[data-view="month"] .routine-planner-run .routine-planner-avatars {
  @apply [display:none];
}

/* Days of the months before and after only fill the rows. */
.routine-planner-day[data-outside] {
  @apply [border-color:var(--johnbot-border)];
  @apply [background:var(--johnbot-transparent)];
}

.routine-planner-day[data-outside] .routine-planner-day-button strong {
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-weight:var(--johnbot-weight-regular)];
}

.routine-planner-upcoming,
.routine-planner-day-view {
  @apply [display:grid];
  @apply [min-width:0];
  @apply [align-content:start];
  @apply [gap:var(--johnbot-space-2)];
}

.routine-planner-upcoming {
  @apply [border:1px_solid_var(--johnbot-border-strong)];
  @apply [border-radius:var(--johnbot-radius-lg)];
  @apply [padding:var(--johnbot-space-3)];
}

.routine-planner-upcoming h3,
.routine-planner-hour h3 {
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [font-weight:var(--johnbot-weight-medium)];
}

.routine-planner-hour {
  @apply [display:grid];
  @apply [grid-template-columns:4rem_minmax(0,_1fr)];
  @apply [align-items:start];
  @apply [gap:var(--johnbot-space-2)];
  @apply [border-top:1px_solid_var(--johnbot-border-strong)];
  @apply [padding-top:var(--johnbot-space-2)];
}

.routine-planner-hour h3 {
  @apply [padding-top:var(--johnbot-space-2)];
  @apply [font-variant-numeric:tabular-nums];
}

.routine-planner-entry {
  @apply [display:flex];
  @apply [min-width:0];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-1)];
}

.routine-planner-entry-main.ui-button {
  @apply [display:flex];
  @apply [min-width:0];
  @apply [height:auto];
  @apply [flex:1_1_auto];
  @apply [align-items:center];
  @apply [justify-content:flex-start];
  @apply [gap:var(--johnbot-space-2)];
  @apply [border-radius:var(--johnbot-radius-md)];
  @apply [padding:var(--johnbot-space-1-5)_var(--johnbot-space-2)];
  @apply [text-align:left];
}

.routine-planner-entry-text {
  @apply [display:grid];
  @apply [min-width:0];
}

.routine-planner-entry-name,
.routine-planner-entry-meta {
  @apply [overflow:hidden];
  @apply [text-overflow:ellipsis];
  @apply [white-space:nowrap];
}

.routine-planner-entry-name {
  @apply [font-size:var(--johnbot-text-md)];
}

.routine-planner-entry-meta {
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [font-weight:var(--johnbot-weight-regular)];
}

.routine-planner-entry[data-status="failed"] .routine-planner-entry-meta {
  @apply [color:var(--johnbot-danger-text)];
}

.routine-planner-entry-agents {
  @apply [display:flex];
  @apply [flex:0_0_auto];
}

.routine-planner-agent .routine-planner-avatar.agent-avatar {
  @apply [width:var(--johnbot-control-xs)];
  @apply [height:var(--johnbot-control-xs)];
}

/*
 * The calendar before its first routine: a faint month behind the pitch. The month and the pitch
 * share one grid cell. Sample runs land on the month one at a time and write a note.
 */
.routine-planner-empty,
.routine-planner-empty-board {
  @apply [display:grid];
  @apply [min-width:0];
}

.routine-planner-empty > *,
.routine-planner-empty-board > * {
  @apply [grid-area:1_/_1];
}

.routine-planner-empty-board {
  @apply [pointer-events:none];
  @apply [user-select:none];
}

.routine-planner-empty-cells,
.routine-planner-empty-runs {
  @apply [display:grid];
  @apply [min-width:0];
  @apply [grid-template-columns:repeat(7,_minmax(0,_1fr))];
  @apply [grid-auto-rows:10rem];
}

/* Only hairlines. They clear behind the pitch and fade towards every edge. */
.routine-planner-empty-cells {
  @apply [mask-image:radial-gradient(ellipse_36%_36%_at_50%_50%,_var(--johnbot-transparent)_68%,_var(--johnbot-text-primary)_100%),_radial-gradient(ellipse_72%_78%_at_50%_50%,_var(--johnbot-text-primary)_50%,_var(--johnbot-transparent)_100%)];
  @apply [mask-composite:intersect];
}

.routine-planner-empty-cell {
  @apply [border-top:1px_solid_var(--johnbot-border)];
  @apply [border-left:1px_solid_var(--johnbot-border)];
  @apply [padding:var(--johnbot-space-2)_var(--johnbot-space-3)];
  @apply [color:var(--johnbot-text-dim)];
  @apply [font-size:var(--johnbot-text-md)];
}

.routine-planner-empty-cell[data-outside] {
  @apply [opacity:0.45];
}

.routine-planner-empty-cell[data-today] {
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-weight:var(--johnbot-weight-semibold)];
}

/* A run lands, writes its note, holds, then fades. The animation is `LIFE` steps of `STEP_MS`. */
.routine-planner-empty-run {
  @apply [display:grid];
  @apply [min-width:0];
  @apply [align-self:start];
  @apply [justify-items:start];
  @apply [gap:var(--johnbot-space-2)];
  @apply [grid-row:var(--routine-planner-empty-row)];
  @apply [grid-column:var(--routine-planner-empty-column)];
  @apply [margin-top:calc(var(--johnbot-space-8)_+_var(--johnbot-space-1))];
  @apply [padding-inline:var(--johnbot-space-2)];
  @apply [animation:routine-planner-empty-life_var(--routine-planner-empty-life)_var(--johnbot-ease-out)_both];
}

.routine-planner-empty-run > .routine-planner-run {
  @apply [width:100%];
}

.routine-planner-empty-day {
  @apply [display:none];
}

.routine-planner-empty-check {
  @apply [stroke-dasharray:24];
  @apply [stroke-dashoffset:24];
  @apply [opacity:0];
  @apply [animation:routine-planner-empty-draw_420ms_var(--johnbot-ease-out)_380ms_forwards];
}

@keyframes routine-planner-empty-life {
  0% {
    opacity: 0;
    filter: blur(4px);
    transform: translateY(10px) scale(0.96);
  }

  8%,
  88% {
    opacity: 1;
    filter: blur(0);
    transform: none;
  }

  100% {
    opacity: 0;
    filter: blur(3px);
    transform: translateY(-4px);
  }
}

@keyframes routine-planner-empty-draw {
  from {
    opacity: 1;
  }

  to {
    opacity: 1;
    stroke-dashoffset: 0;
  }
}

/* Handwriting. The app has no hand font, so it uses the one of the system. */
.routine-planner-hand {
  @apply [color:var(--johnbot-accent-text)];
  font-family: "Bradley Hand", "Noteworthy", "Segoe Print", cursive;
  @apply [font-weight:var(--johnbot-weight-semibold)];
}

.routine-planner-empty-note {
  @apply [display:grid];
  @apply [width:fit-content];
  @apply [padding-inline:var(--johnbot-space-1)];
  @apply [font-size:var(--johnbot-text-xl)];
  @apply [line-height:1.3];
  @apply [transform:rotate(-1.5deg)];
  @apply [transform-origin:left_top];
}

/* Each line writes itself from left to right, at the speed of its length. */
.routine-planner-empty-line {
  @apply [clip-path:inset(-0.4em_100%_-0.4em_-0.2em)];
  @apply [animation:routine-planner-empty-write_var(--routine-planner-empty-length)_linear_var(--routine-planner-empty-delay)_forwards];
}

@keyframes routine-planner-empty-write {
  to {
    clip-path: inset(-0.4em -0.2em -0.4em -0.2em);
  }
}

.routine-planner-empty-underline {
  @apply [width:100%];
  @apply [height:var(--johnbot-space-2)];
  @apply [overflow:visible];
}

.routine-planner-empty-underline path {
  @apply [fill:none];
  @apply [stroke:currentColor];
  @apply [stroke-dasharray:1];
  @apply [stroke-dashoffset:1];
  @apply [stroke-linecap:round];
  @apply [opacity:0];
  @apply [stroke-width:1.5];
  @apply [vector-effect:non-scaling-stroke];
  @apply [animation:routine-planner-empty-draw_520ms_var(--johnbot-ease-out)_var(--routine-planner-empty-delay)_forwards];
}

.routine-planner-empty-pitch {
  @apply [z-index:1];
  @apply [display:grid];
  @apply [max-width:34rem];
  @apply [place-self:center];
  @apply [justify-items:center];
  @apply [gap:var(--johnbot-space-4)];
  @apply [padding:var(--johnbot-space-6)];
  @apply [text-align:center];
}

.routine-planner-empty-title {
  @apply [display:grid];
  @apply [font-size:var(--johnbot-text-display)];
  @apply [font-weight:var(--johnbot-weight-semibold)];
  @apply [letter-spacing:-0.01em];
  @apply [line-height:1.2];
}

.routine-planner-empty-title > .routine-planner-empty-lead {
  @apply [color:var(--johnbot-text-muted)];
}

/* The one handwritten word of the title. It writes itself once. */
/* Inline, not inline-block: a reader then hears "done." with no space before the full stop. */
.routine-planner-empty-done {
  @apply [clip-path:inset(-0.4em_100%_-0.4em_-0.2em)];
  @apply [animation:routine-planner-empty-write_520ms_linear_500ms_forwards];
}

.routine-planner-empty-lines {
  @apply [display:grid];
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-xl)];
  @apply [line-height:1.5];
}

.routine-planner-empty-action.ui-button {
  @apply [width:100%];
  @apply [max-width:22rem];
  @apply [height:var(--johnbot-control-lg)];
  @apply [margin-top:var(--johnbot-space-2)];
}

.routine-planner-empty-menu {
  @apply [min-width:14rem];
  @apply [max-height:min(520px,_calc(100dvh_-_16px),_var(--kb-popper-content-available-height,_520px))];
  @apply [overflow-y:auto];
}

/* Less motion: one still frame with three runs and their notes. */
.routine-planner-empty[data-still]
:is(
  .routine-planner-empty-run,
  .routine-planner-empty-check,
  .routine-planner-empty-line,
  .routine-planner-empty-underline path,
  .routine-planner-empty-done
) {
  @apply [animation:none];
  @apply [clip-path:none];
  @apply [stroke-dashoffset:0];
  @apply [opacity:1];
}

.routine-planner-skeleton-heading {
  @apply [height:var(--johnbot-control-xs)];
}

.routine-planner-skeleton-run {
  @apply [height:var(--johnbot-control-md)];
}

/* Seven day columns need the full width: the next runs move below the week. */
@container (max-width: 1160px) {
  .routine-planner-body {
    @apply [grid-template-columns:minmax(0,_1fr)];
  }
}

/* A narrow pane, such as a phone or a side panel: the week becomes a list of days. */
@container (max-width: 920px) {
  .routine-planner-week {
    @apply [grid-template-columns:minmax(0,_1fr)];
  }

  .routine-planner-day {
    @apply [min-height:0];
    @apply [grid-template-columns:5rem_minmax(0,_1fr)];
    @apply [align-items:start];
  }

  .routine-planner-day > :not(.routine-planner-day-heading) {
    @apply [grid-column:2];
  }

  .routine-planner-loading .routine-planner-day {
    @apply [grid-template-columns:minmax(0,_1fr)];
  }

  .routine-planner-loading .routine-planner-day > * {
    @apply [grid-column:1];
  }

  /* The month becomes a list of its own days: each day names its weekday again. */
  .routine-planner-weekdays,
  .routine-planner-day[data-outside] {
    @apply [display:none];
  }

  .routine-planner[data-view="month"] .routine-planner-day {
    @apply [min-height:0];
  }

  .routine-planner[data-view="month"] .routine-planner-day-button > span {
    @apply [display:inline];
  }

  /* The pitch comes first, then one row for each run on screen. */
  .routine-planner-empty > .routine-planner-empty-board {
    @apply [grid-area:2_/_1];
  }

  .routine-planner-empty-pitch {
    @apply [padding-inline:0];
  }

  .routine-planner-empty-title {
    @apply [font-size:var(--johnbot-text-3xl)];
  }

  .routine-planner-empty-lines {
    @apply [font-size:var(--johnbot-text-lg)];
  }

  .routine-planner-empty-cells {
    @apply [display:none];
  }

  .routine-planner-empty-runs {
    @apply [grid-template-columns:minmax(0,_1fr)];
    @apply [grid-template-rows:repeat(3,_8rem)];
    @apply [grid-auto-rows:0];
  }

  .routine-planner-empty-run {
    @apply [width:100%];
    @apply [grid-row:var(--routine-planner-empty-slot)];
    @apply [grid-column:1];
    @apply [margin-top:0];
    @apply [padding-inline:0];
