  --trace-lane-pad: var(--johnbot-space-3);
  --trace-row-height: 36px;
  --trace-bar-height: 16px;
  /* The colour of the agent that did a span. The top agent and its own calls stay neutral. */
  --trace-hue: var(--johnbot-text-muted);
  @apply [display:flex];
  @apply [min-width:0];
  @apply [min-height:0];
  @apply [max-height:100%];
  @apply [flex:1_1_auto];
  @apply [flex-direction:column];
  @apply [overflow:hidden];
  @apply [border:1px_solid_var(--johnbot-border)];
  @apply [border-radius:var(--johnbot-radius-card)];
  @apply [background:var(--trace-surface)];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [line-height:var(--johnbot-leading-sm)];
}

