/*
 * The close button reads as a control, not as the action the card offers: the tinted fill above
 * belongs to the one button that resolves a state (Sign in), and an X that carried the same fill
 * would compete with it wherever both appear. It takes the accent only under the pointer.
 */
.composer-notice-dismiss {
  @apply [flex:none];
  @apply [align-self:flex-start];
}

.composer-notice .composer-notice-dismiss {
  @apply [background:transparent];
  @apply [color:var(--notice-accent)];
}

@media (hover: hover) {
  .composer-notice .composer-notice-dismiss:hover:not(:disabled):not([data-disabled]) {
    @apply [background:color-mix(in_srgb,_var(--notice-accent)_18%,_transparent)];
