/* Composer notice ------------------------------------------------------- */

/* The end is a result, not a wait, so it takes the tone the conversation row gives a completed compaction. */
.context-compaction-notice[data-tone="success"] {
  --notice-accent: var(--johnbot-success-text);
  --notice-surface: var(--johnbot-success-soft);
