}

.file-row[data-status="missing"] .file-row-name {
  @apply [color:var(--johnbot-text-muted)];
  @apply [text-decoration:line-through];
  @apply [text-decoration-color:var(--johnbot-text-dim)];
}

.file-row-meta {
  @apply [display:flex];
  @apply [min-width:0];
  @apply [overflow:hidden];
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-sm)];
