}

.file-row-menu-trigger {
  @apply [flex:0_0_auto];
  @apply [color:var(--johnbot-text-muted)];
}

.file-row-menu-trigger > svg {
  @apply [width:var(--johnbot-icon-md)];
  @apply [height:var(--johnbot-icon-md)];
  @apply [stroke-width:var(--johnbot-icon-stroke)];
}

/* Icons next to button text: the ui-button leaves lucide at its 24px default. */
.files-button-icon {
  @apply [width:var(--johnbot-icon-sm)];
  @apply [height:var(--johnbot-icon-sm)];
  @apply [flex:0_0_auto];
  @apply [stroke-width:var(--johnbot-icon-stroke)];
}

/* Agent settings > Files ------------------------------------------------- */

.agent-files-view {
  @apply [position:absolute];
  @apply [z-index:2];
  @apply [inset:0];
  @apply [display:flex];
  @apply [flex-direction:column];
