}

.agent-files-body {
  @apply [container-type:inline-size];
  @apply [display:flex];
  @apply [min-height:0];
  @apply [flex:1];
  @apply [flex-direction:column];
  @apply [gap:var(--johnbot-space-6)];
  @apply [overflow-y:auto];
  @apply [padding:var(--johnbot-space-4)];
}

.agent-files-summary {
  @apply [display:flex];
  @apply [flex-direction:column];
  @apply [gap:var(--johnbot-space-3)];
}

.agent-files-total-label {
