}

.agent-files-tile {
  @apply [display:flex];
  @apply [min-height:36px];
  @apply [align-items:center];
  @apply [justify-content:space-between];
  @apply [gap:var(--johnbot-space-3)];
  @apply [padding:var(--johnbot-space-2)_var(--johnbot-space-3)];
}

.agent-files-tile + .agent-files-tile {
  @apply [border-top:1px_solid_var(--johnbot-border-grouped)];
}

.agent-files-tile dt {
  @apply [display:flex];
  @apply [min-width:0];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-1)];
  @apply [color:var(--johnbot-text-secondary)];
  @apply [font-size:var(--johnbot-text-md)];
}

.agent-files-tile-label {
  @apply [overflow:hidden];
  @apply [text-overflow:ellipsis];
  @apply [white-space:nowrap];
}

.agent-files-tile dd {
  @apply [margin:0];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-md)];
  @apply [font-variant-numeric:tabular-nums];
}

/* The row keeps its height: the button overlaps the row padding, not the text. */
.agent-files-tile-action {
  @apply [flex:0_0_auto];
  @apply [margin-block:calc(var(--johnbot-space-1)_*_-1)];
  @apply [color:var(--johnbot-text-muted)];
}

.agent-files-tile-skeleton {
  @apply [width:64px];
  @apply [height:18px];
}

.agent-files-section {
  @apply [display:flex];
  @apply [flex-direction:column];
  @apply [gap:var(--johnbot-space-2)];
}

/* Chat > Files panel ------------------------------------------------------ */

.conversation-files-summary {
  @apply [flex:0_0_auto];
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [font-variant-numeric:tabular-nums];
}

.conversation-files-content {
  @apply [min-height:0];
  @apply [flex:1];
  @apply [overflow-y:auto];
  @apply [padding:var(--johnbot-space-3)];
}

/* Machine use, at the top of Storage -------------------------------------- */

.machine-resources-metrics,
.machine-resources-settings {
  @apply [margin:0];
  @apply [padding:0];
  @apply [border:1px_solid_var(--johnbot-border-grouped)];
  @apply [border-radius:var(--johnbot-radius-lg)];
  @apply [background:var(--johnbot-bg-grouped)];
  @apply [list-style:none];
}

.machine-resources-metric {
  @apply [display:grid];
  @apply [grid-template-columns:auto_minmax(0,_1fr)_96px_44px];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-3)];
  @apply [padding:var(--johnbot-space-3)_var(--johnbot-space-4)];
}

.machine-resources-metric + .machine-resources-metric {
  @apply [border-top:1px_solid_var(--johnbot-border-grouped)];
}

.machine-resources-icon {
  @apply [width:var(--johnbot-icon-sm)];
  @apply [height:var(--johnbot-icon-sm)];
  @apply [color:var(--johnbot-text-secondary)];
}

.machine-resources-metric[data-tone="warning"] .machine-resources-icon {
  @apply [color:var(--johnbot-warning)];
}

.machine-resources-metric[data-tone="danger"] .machine-resources-icon {
  @apply [color:var(--johnbot-danger)];
}

.machine-resources-copy {
  @apply [display:grid];
  @apply [min-width:0];
  @apply [gap:var(--johnbot-space-0-5)];
}

.machine-resources-title {
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [font-weight:var(--johnbot-weight-medium)];
}

.machine-resources-meta {
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-sm)];
}

.machine-resources-bar {
  @apply [position:relative];
  @apply [display:flex];
  @apply [align-items:center];
}

.machine-resources-bar .ui-progress-track {
  @apply [height:6px];
}

.machine-resources-metric[data-tone="warning"] .ui-progress-fill {
  @apply [background:var(--johnbot-warning)];
}

.machine-resources-metric[data-tone="danger"] .ui-progress-fill {
  @apply [background:var(--johnbot-danger)];
}

/* The alert level of the metric, on its bar. */
.machine-resources-threshold {
  @apply [position:absolute];
  @apply [top:-3px];
  @apply [bottom:-3px];
  @apply [width:2px];
  @apply [border-radius:var(--johnbot-radius-pill)];
  @apply [background:var(--johnbot-text-secondary)];
}

.machine-resources-value {
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [font-variant-numeric:tabular-nums];
  @apply [text-align:end];
}

.storage-message.machine-resources-alert .storage-message-icon {
  @apply [color:var(--johnbot-warning)];
}

.machine-resources-settings {
  @apply [display:flex];
  @apply [flex-direction:column];
  @apply [gap:var(--johnbot-space-4)];
  @apply [padding:var(--johnbot-space-4)];
}

.machine-resources-setting {
  @apply [display:flex];
  @apply [align-items:center];
  @apply [justify-content:space-between];
  @apply [gap:var(--johnbot-space-4)];
}

.machine-resources-select {
  @apply [flex:0_0_220px];
}

@container (max-width: 520px) {
  .machine-resources-metric {
    @apply [grid-template-columns:auto_minmax(0,_1fr)_44px];
  }

  .machine-resources-bar {
    @apply [display:none];
  }

  .machine-resources-setting {
    @apply [flex-direction:column];
    @apply [align-items:stretch];
  }

  .machine-resources-select {
    @apply [flex-basis:auto];
  }
}

/* === from: @johnbot/ui/features/import/agent-import.css === */
/* Server settings > Import. The review and result use the Storage page's summary, section and
   row styles (features/files/files.css), so the two tabs read as one set. The guide is a single
   sequence: three connected steps, and the file button as the one strong control. */

.agent-import-guide {
  @apply [display:flex];
  @apply [max-width:560px];
  @apply [flex-direction:column];
  @apply [gap:var(--johnbot-space-6)];
}

.agent-import-intro {
  @apply [display:flex];
  @apply [flex-direction:column];
  @apply [gap:var(--johnbot-space-1-5)];
}

.agent-import-heading {
  @apply [margin:0];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-xl)];
  @apply [font-weight:var(--johnbot-weight-semibold)];
  @apply [letter-spacing:-0.01em];
}

.agent-import-lede {
  @apply [margin:0];
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-md)];
  @apply [line-height:1.5];
}

/* The steps are a real sequence, so they keep their numbers. A rule between the markers joins them. */
.agent-import-steps {
  @apply [display:flex];
  @apply [flex-direction:column];
  @apply [margin:0];
  @apply [padding:0];
  @apply [list-style:none];
}

.agent-import-step {
  @apply [position:relative];
  @apply [display:grid];
  @apply [grid-template-columns:24px_minmax(0,_1fr)];
  @apply [column-gap:var(--johnbot-space-4)];
  @apply [padding-bottom:var(--johnbot-space-6)];
}

.agent-import-step:last-child {
  @apply [padding-bottom:0];
}

.agent-import-step:not(:last-child)::before {
  @apply [position:absolute];
  @apply [top:28px];
  @apply [bottom:4px];
  @apply [left:11.5px];
  @apply [width:1px];
  @apply [background:var(--johnbot-border-grouped)];
  content: "";
}

.agent-import-marker {
  @apply [display:inline-flex];
  @apply [width:24px];
  @apply [height:24px];
  @apply [align-items:center];
  @apply [justify-content:center];
  @apply [border:1px_solid_var(--johnbot-border-strong)];
  @apply [border-radius:var(--johnbot-radius-pill)];
  @apply [color:var(--johnbot-text-secondary)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [font-variant-numeric:tabular-nums];
  @apply [font-weight:var(--johnbot-weight-medium)];
}

.agent-import-step-body {
  @apply [display:flex];
  @apply [min-width:0];
  @apply [flex-direction:column];
  @apply [align-items:flex-start];
  @apply [gap:var(--johnbot-space-2)];
  @apply [padding-top:2px];
}

.agent-import-step-title {
  @apply [margin:0];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-md)];
  @apply [font-weight:var(--johnbot-weight-medium)];
}

.agent-import-step-note {
  @apply [margin:0];
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [line-height:1.45];
}

/* Two ways into Grok Bot share step 1: the ready agent from its link, or the skill added by hand. */
.agent-import-setup {
  @apply [display:flex];
  @apply [width:100%];
  @apply [flex-direction:column];
  @apply [align-items:flex-start];
  @apply [gap:var(--johnbot-space-3)];
}

.agent-import-setup .ui-sliding-tabs-content-slot {
  @apply [width:100%];
}

/* The folder panel is the tallest and has no steps after it, so when it is hidden it takes no space.
   The panels that do have steps after them share one height, so steps 2 and 3 never move. */
.agent-import-setup-folder:not([data-selected]) {
  @apply [display:none];
}

.agent-import-setup-panel {
  @apply [display:flex];
  @apply [flex-direction:column];
  @apply [align-items:flex-start];
  @apply [gap:var(--johnbot-space-2)];
}

/* One card per way in, the same shape in both panels, so step 2 stays where it is: the ready agent
   with its link, or the skill file with both ways to take it. */
.agent-import-card {
  @apply [display:flex];
  @apply [width:100%];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-3)];
  @apply [padding:var(--johnbot-space-2)_var(--johnbot-space-2)_var(--johnbot-space-2)_var(--johnbot-space-3)];
  @apply [border:1px_solid_var(--johnbot-border-grouped)];
  @apply [border-radius:var(--johnbot-radius-md)];
  @apply [background:var(--johnbot-bg-grouped)];
}

.agent-import-card-icon {
  @apply [width:var(--johnbot-icon-md)];
  @apply [height:var(--johnbot-icon-md)];
  @apply [flex:none];
  @apply [color:var(--johnbot-text-secondary)];
  @apply [stroke-width:var(--johnbot-icon-stroke)];
}

.agent-import-card-copy {
  @apply [display:flex];
  @apply [min-width:0];
  @apply [flex:1];
  @apply [flex-direction:column];
}

.agent-import-card-name {
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-md)];
  @apply [font-weight:var(--johnbot-weight-medium)];
}

.agent-import-card-meta {
  @apply [overflow:hidden];
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [text-overflow:ellipsis];
  @apply [white-space:nowrap];
}

/* The exact words to send, shown as the text itself rather than described. */
.agent-import-prompt {
  @apply [display:flex];
  @apply [width:100%];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-2)];
  @apply [padding:var(--johnbot-space-1)_var(--johnbot-space-1)_var(--johnbot-space-1)_var(--johnbot-space-3)];
  @apply [border:1px_solid_var(--johnbot-border-grouped)];
  @apply [border-radius:var(--johnbot-radius-md)];
  @apply [background:var(--johnbot-bg-grouped)];
}

.agent-import-prompt-text {
  @apply [min-width:0];
  @apply [flex:1];
  @apply [overflow:hidden];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-md)];
  @apply [text-overflow:ellipsis];
  @apply [white-space:nowrap];
}

.agent-import-prompt svg {
  @apply [width:var(--johnbot-icon-sm)];
  @apply [height:var(--johnbot-icon-sm)];
  @apply [stroke-width:var(--johnbot-icon-stroke)];
}

.agent-import-card .ui-button svg {
  @apply [width:var(--johnbot-icon-sm)];
  @apply [height:var(--johnbot-icon-sm)];
  @apply [stroke-width:var(--johnbot-icon-stroke)];
}

.agent-import-picker.ui-button {
  @apply [display:flex];
  @apply [width:100%];
  @apply [height:auto];
  @apply [min-height:64px];
  @apply [align-items:center];
  @apply [justify-content:flex-start];
  @apply [gap:var(--johnbot-space-3)];
  @apply [padding:var(--johnbot-space-3)_var(--johnbot-space-4)];
  @apply [border:1px_solid_var(--johnbot-border-grouped)];
  @apply [border-radius:var(--johnbot-radius-lg)];
  @apply [background:var(--johnbot-bg-grouped)];
  @apply [text-align:left];
  @apply [font-weight:var(--johnbot-weight-regular)];
}

.agent-import-picker.ui-button:hover:not(:disabled, [aria-disabled="true"]) {
  @apply [border-color:var(--johnbot-border-strong)];
  @apply [background:var(--johnbot-bg-control-hover)];
}

.agent-import-picker-icon {
  @apply [width:var(--johnbot-icon-lg)];
  @apply [height:var(--johnbot-icon-lg)];
  @apply [flex:0_0_auto];
  @apply [color:var(--johnbot-text-secondary)];
  @apply [stroke-width:var(--johnbot-icon-stroke)];
}

.agent-import-picker-copy {
  @apply [display:flex];
  @apply [min-width:0];
  @apply [flex-direction:column];
  @apply [gap:var(--johnbot-space-0-5)];
}

.agent-import-picker-title {
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-md)];
  @apply [font-weight:var(--johnbot-weight-medium)];
}

.agent-import-picker-meta {
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-sm)];
}

/* Review and result rows. */

.agent-import-row {
  @apply [display:flex];
  @apply [min-height:52px];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-3)];
  @apply [padding:var(--johnbot-space-3)_var(--johnbot-space-4)];
}

label.agent-import-row {
  @apply [cursor:pointer];
}

label.agent-import-row:hover {
  @apply [background:var(--johnbot-hover)];
}

label.agent-import-row:has(input:disabled) {
  @apply [cursor:default];
}

.agent-import-row-note {
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [line-height:1.4];
}

.agent-import-notes {
  @apply [display:flex];
  @apply [flex-direction:column];
  @apply [gap:var(--johnbot-space-1)];
  @apply [margin:var(--johnbot-space-1)_0_0];
  @apply [padding:0];
  @apply [list-style:none];
}

.agent-import-done {
  @apply [display:flex];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-2)];
}

.agent-import-done-icon {
  @apply [width:32px];
  @apply [height:32px];
  @apply [flex:0_0_auto];
  @apply [color:var(--johnbot-success-text)];
  @apply [stroke-width:var(--johnbot-icon-stroke)];
}

.agent-import-skipped-icon {
  @apply [color:var(--johnbot-warning-text)];
}

.agent-import-actions {
  @apply [display:flex];
  @apply [flex-wrap:wrap];
  @apply [justify-content:flex-end];
  @apply [gap:var(--johnbot-space-2)];
}

/* The name and, for a name already on this server, the hint that the import adds another one. */
.agent-import-row-title {
  @apply [display:flex];
  @apply [min-width:0];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-1)];
}

.agent-import-name-hint {
  @apply [display:inline-flex];
  @apply [flex:none];
  @apply [color:var(--johnbot-text-muted)];
  @apply [border-radius:var(--johnbot-radius-sm)];
}

.agent-import-name-hint:hover,
.agent-import-name-hint:focus-visible {
  @apply [color:var(--johnbot-text-secondary)];
}

.agent-import-name-hint svg {
  @apply [width:var(--johnbot-icon-xs)];
  @apply [height:var(--johnbot-icon-xs)];
  @apply [stroke-width:var(--johnbot-icon-stroke)];
}

/* A channel row shows up to three of its members, overlapped, where an agent row has one avatar. */
.agent-import-members {
  @apply [display:flex];
  @apply [flex:none];
  @apply [width:44px];
}

.agent-import-member-avatar {
  @apply [width:22px];
  @apply [height:22px];
  @apply [flex:none];
  @apply [border-radius:var(--johnbot-radius-pill)];
