  @apply [height:var(--johnbot-icon-sm)];
}

.integration-effects li[data-tone="danger"] .integration-effect-icon {
  @apply [background:var(--johnbot-danger-soft)];
  @apply [color:var(--johnbot-danger-text)];
}

.integration-effects li[data-tone="success"] .integration-effect-icon {
  @apply [background:var(--johnbot-success-soft)];
  @apply [color:var(--johnbot-success)];
}

/* The label on the soft danger fill reads the text step, as the shared confirmation does for contrast. */
.integration-confirm.ui-button-variant-destructive {
  @apply [color:var(--johnbot-danger-text)];
}

/* ------------------------------------------------ linked rows */

/* The whole row opens the integration, as on Marketplace cards. Buttons in the row stay on top. */
.integrations-hub-row {
  @apply [position:relative];
  @apply [border-radius:var(--johnbot-radius-md)];
