}

.integrations-hub-hitarea {
  @apply [position:absolute];
  @apply [z-index:1];
  @apply [inset:0];
  @apply [width:auto];
  @apply [height:auto];
  @apply [padding:0];
  @apply [border:0];
  @apply [border-radius:inherit];
  @apply [background:var(--johnbot-transparent)];
  @apply [cursor:pointer];
  @apply [transition:none];
}

.integrations-hub-hitarea:hover:not(:disabled):not([data-disabled]) {
