}

.integrations-hub-hitarea:focus-visible {
  @apply [outline:2px_solid_var(--johnbot-border-focus)];
  @apply [outline-offset:-2px];
}

.integrations-hub-actions {
  @apply [gap:var(--johnbot-space-3)];
}

.integrations-hub-actions .ui-button {
  @apply [position:relative];
  @apply [z-index:2];
}

.integrations-hub-chevron {
  @apply [width:var(--johnbot-icon-sm)];
  @apply [height:var(--johnbot-icon-sm)];
  @apply [margin:0_var(--johnbot-space-1-5)];
  @apply [color:var(--johnbot-text-muted)];
}

.integrations-face-stack {
  @apply [display:inline-flex];
  @apply [gap:var(--johnbot-space-0-5)];
  @apply [align-items:center];
}

.integrations-face-more {
  @apply [display:inline-grid];
  @apply [min-width:24px];
  @apply [height:24px];
  @apply [padding:0_var(--johnbot-space-1)];
  @apply [place-items:center];
  @apply [border-radius:var(--johnbot-radius-pill)];
  @apply [background:var(--johnbot-bg-control)];
  @apply [color:var(--johnbot-text-secondary)];
  @apply [font-size:var(--johnbot-text-sm)];
}

.integrations-agent-face {
  --integrations-agent-face-size: 32px;
  @apply [display:inline-block];
  @apply [flex:none];
  @apply [width:var(--integrations-agent-face-size)];
  @apply [height:var(--integrations-agent-face-size)];
}

.integrations-agent-face[data-size="sm"] {
  --integrations-agent-face-size: 24px;
}

/* An agent avatar stands low in its box. Lift it to the middle, as the marketplace avatar does. */
.integrations-agent-face > * {
  --agent-avatar-optical-offset: calc(var(--integrations-agent-face-size) * -0.14);
  @apply [width:100%];
  @apply [height:100%];
}

/* === from: @johnbot/ui/features/settings/provider-settings-page.css === */
/* Settings > Providers. The settings card and row classes do the layout; these rules add only what
   they do not have. */

.provider-settings-stack {
