}

.provider-settings-progress {
  @apply [max-width:320px];
}

/* === from: @johnbot/ui/features/settings/github-connector.css === */
/* UserAvatar has no style of its own: the initials, or GitHub's picture when the account has one. */
.github-connector-avatar {
  @apply [display:inline-grid];
  @apply [flex:none];
  @apply [width:32px];
  @apply [height:32px];
  @apply [place-items:center];
  @apply [overflow:hidden];
  @apply [border-radius:var(--johnbot-radius-pill)];
  @apply [background:linear-gradient(135deg,_var(--johnbot-accent-strong),_var(--johnbot-onboarding-desktop-indigo))];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [font-weight:var(--johnbot-weight-semibold)];
}

.github-connector-avatar > img {
  @apply [width:100%];
  @apply [height:100%];
  @apply [object-fit:cover];
}

.github-connector-search {
  @apply [position:relative];
  @apply [display:flex];
  @apply [align-items:center];
}

.github-connector-search > svg {
  @apply [position:absolute];
  @apply [left:var(--johnbot-space-3)];
  @apply [width:var(--johnbot-icon-sm)];
  @apply [height:var(--johnbot-icon-sm)];
  @apply [color:var(--johnbot-text-muted)];
  @apply [pointer-events:none];
}

.github-connector-search input {
  @apply [width:100%];
  @apply [padding-left:calc(var(--johnbot-space-3)_*_2_+_var(--johnbot-icon-sm))];
}

/* A long list scrolls inside the card, so Disconnect stays near the top of the tab. The rows' hover fill goes past
   the text, so the names line up with the search field. */
.github-connector-repository-list {
  @apply [display:grid];
  @apply [max-height:260px];
  @apply [margin:0_calc(var(--johnbot-space-2)_*_-1)];
  @apply [padding:0];
  @apply [overflow-y:auto];
  @apply [list-style:none];
}

.github-connector-repository {
  @apply [display:flex];
  @apply [gap:var(--johnbot-space-2)];
  @apply [align-items:center];
  @apply [justify-content:space-between];
  /* The same height with and without the Private badge. */
  @apply [min-height:36px];
  @apply [padding:0_var(--johnbot-space-2)];
  @apply [border-radius:var(--johnbot-radius-md)];
  @apply [transition:background-color_var(--johnbot-duration-fast)_var(--johnbot-ease-out)];
}

.github-connector-repository:hover {
  @apply [background:var(--johnbot-hover)];
}

.github-connector-repository-name {
  @apply [min-width:0];
}

.github-connector-repository-owner {
  @apply [color:var(--johnbot-text-muted)];
}

.github-connector-private {
  @apply [flex:none];
  @apply [gap:var(--johnbot-space-1)];
}

/* ------------------------------------------------ connect dialog */

.github-connector-center {
  @apply [display:grid];
  @apply [min-height:96px];
  @apply [place-items:center];
}

/* The code is about to be typed on another screen, so each character has its own tile. */
.github-connector-code {
  @apply [display:flex];
  @apply [gap:var(--johnbot-space-1-5)];
  @apply [justify-content:center];
}

.github-connector-code-char {
  @apply [display:inline-grid];
  @apply [width:36px];
  @apply [height:48px];
  @apply [place-items:center];
  @apply [border:1px_solid_var(--johnbot-border)];
  @apply [border-radius:var(--johnbot-radius-md)];
  @apply [background:var(--johnbot-bg-surface)];
  @apply [font-family:var(--johnbot-font-mono)];
  @apply [font-size:var(--johnbot-text-xl)];
  @apply [font-weight:var(--johnbot-weight-semibold)];
}

.github-connector-code-char[data-separator="true"] {
  @apply [width:12px];
  @apply [border-color:var(--johnbot-transparent)];
  @apply [background:var(--johnbot-transparent)];
  @apply [color:var(--johnbot-text-muted)];
}

.github-connector-waiting {
  @apply [display:flex];
  @apply [gap:var(--johnbot-space-2)];
  @apply [align-items:center];
  @apply [justify-content:center];
}

.github-connector-done {
  @apply [display:flex];
  @apply [gap:var(--johnbot-space-3)];
  @apply [align-items:center];
  @apply [padding:var(--johnbot-space-3)_var(--johnbot-space-4)];
  @apply [border-radius:var(--johnbot-radius-lg)];
  @apply [background:var(--johnbot-success-wash)];
}

.github-connector-done > div {
  @apply [display:grid];
  @apply [flex:1];
}

/* === from: @johnbot/ui/features/settings/onepassword-connector.css === */
/* A vault secret: the labelled field, and its buttons in line with the field, not with the label. */
.vault-secret-form {
  @apply [display:flex];
  @apply [align-items:flex-end];
  @apply [gap:var(--johnbot-space-3)];
}

.vault-secret-form > .ui-field {
  @apply [flex:1];
  @apply [min-width:0];
}

.vault-secret-actions {
  @apply [display:flex];
  @apply [gap:var(--johnbot-space-2)];
  @apply [align-items:center];
}

/* A joined server's Bitwarden form: one field per row, the buttons under them. */
.bitwarden-connector-host-form {
  @apply [display:grid];
  @apply [gap:var(--johnbot-space-3)];
}

.bitwarden-connector-actions {
  @apply [display:flex];
  @apply [gap:var(--johnbot-space-2)];
  @apply [align-items:center];
}

/* A step's text is its instruction, so it wraps instead of ending in an ellipsis. */
.onepassword-connector-step .ui-item-description {
  @apply [white-space:normal];
}

.onepassword-connector-step .ui-item-media {
  @apply [color:var(--johnbot-text-muted)];
}

.onepassword-connector-step[data-step="done"] .ui-item-media {
  @apply [color:var(--johnbot-success)];
}

/* A step whose earlier step is not done is quieter, so the eye goes to the one to do now. */
.onepassword-connector-step[data-step="waiting"] .ui-item-title {
  @apply [color:var(--johnbot-text-muted)];
}

/* === from: @johnbot/ui/features/settings/slack-integration.css === */
/* Marketplace > Apps > Slack, Discord and Telegram: the channel pages (ChannelParts.tsx). */

.channel-stack {
  @apply [display:grid];
  @apply [gap:var(--johnbot-space-0-5)];
  @apply [justify-items:start];
}

/* ------------------------------------------------ connect dialog */

.channel-checklist {
  @apply [display:grid];
  @apply [gap:var(--johnbot-space-2)];
  @apply [margin:0];
  @apply [padding:var(--johnbot-space-3)_var(--johnbot-space-4)];
  @apply [border-radius:var(--johnbot-radius-lg)];
  @apply [background:var(--johnbot-bg-surface)];
  @apply [list-style:none];
  @apply [font-size:var(--johnbot-text-sm)];
}

.channel-checklist li {
  @apply [display:flex];
  @apply [gap:var(--johnbot-space-2)];
  @apply [align-items:center];
}

.channel-checklist li[data-state="done"] {
  @apply [color:var(--johnbot-text-secondary)];
}

.channel-checklist li[data-state="done"] svg {
  @apply [color:var(--johnbot-success)];
}

.channel-checklist-dot {
  @apply [width:14px];
  @apply [height:14px];
  @apply [border:1px_solid_var(--johnbot-border-strong)];
  @apply [border-radius:var(--johnbot-radius-pill)];
}

.channel-waiting {
  @apply [display:flex];
  @apply [gap:var(--johnbot-space-2)];
  @apply [align-items:center];
  @apply [justify-content:center];
}

.channel-orchestrator-card {
  @apply [display:flex];
  @apply [gap:var(--johnbot-space-3)];
  @apply [align-items:center];
  @apply [padding:var(--johnbot-space-3)];
  @apply [border:1px_solid_var(--johnbot-border)];
  @apply [border-radius:var(--johnbot-radius-lg)];
  @apply [background:var(--johnbot-bg-surface)];
}

.channel-orchestrator-model {
  @apply [display:grid];
  @apply [gap:var(--johnbot-space-1)];
}

/* ------------------------------------------------ Discord roles dialog */

.discord-roles {
  @apply [display:grid];
  @apply [max-height:40vh];
  @apply [margin:0];
  @apply [padding:var(--johnbot-space-1)];
  @apply [overflow-y:auto];
  @apply [border:1px_solid_var(--johnbot-border)];
  @apply [border-radius:var(--johnbot-radius-lg)];
  @apply [background:var(--johnbot-bg-surface)];
  @apply [list-style:none];
}

.discord-role-row {
  @apply [display:flex];
  @apply [gap:var(--johnbot-space-2)];
  @apply [align-items:center];
  @apply [padding:var(--johnbot-space-1)_var(--johnbot-space-2)];
  @apply [border-radius:var(--johnbot-radius-sm)];
  @apply [cursor:pointer];
}

.discord-role-row:hover {
  @apply [background:var(--johnbot-bg-control-hover)];
}

.discord-role-name {
  @apply [min-width:0];
  @apply [overflow:hidden];
  @apply [text-overflow:ellipsis];
  @apply [white-space:nowrap];
}

/* === from: @johnbot/ui/features/settings/hosted-servers.css === */
.hosted-servers-add {
  @apply [display:flex];
}

/* The list area before the first list answers. It fades in after a delay, so a fast answer does not flash it. */
.hosted-servers-loading {
  @apply [display:grid];
  @apply [place-items:center];
  @apply [padding:var(--johnbot-space-8)];
  @apply [animation:hosted-servers-loading-in_var(--johnbot-duration-normal)_var(--johnbot-ease-out)_var(--johnbot-loading-indicator-delay)_both];
}

@keyframes hosted-servers-loading-in {
  from {
    opacity: 0;
  }
}

.hosted-servers-list .hosted-servers-row {
  @apply [min-height:64px];
  @apply [align-items:center];
}

.hosted-servers-list .ui-item-content {
  @apply [min-width:0];
}

.hosted-servers-list .ui-item-title {
  @apply [gap:var(--johnbot-space-2)];
}

.hosted-servers-actions {
  @apply [flex-wrap:nowrap];
  @apply [justify-content:flex-end];
}

@media (max-width: 700px) {
  .hosted-servers-list .hosted-servers-row {
    @apply [align-items:flex-start];
    @apply [flex-direction:column];
  }

  .hosted-servers-actions {
    @apply [width:100%];
    @apply [justify-content:flex-start];
  }
}

/* === from: @johnbot/ui/features/settings/profile.css === */
/* The Profile tab of Settings: the header, the year of activity, and its two dialogs. */

.profile-panel {
  @apply [display:flex];
  @apply [flex-direction:column];
  @apply [gap:var(--johnbot-space-6)];
}

/* ─── Header ─── */

.profile-hero {
  @apply [display:flex];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-3)];
}

.profile-hero-avatar {
  @apply [display:grid];
  @apply [place-items:center];
  @apply [flex:none];
  @apply [width:calc(var(--johnbot-space-8)_*_1.75)];
  @apply [aspect-ratio:1];
  @apply [border-radius:var(--johnbot-radius-pill)];
  @apply [overflow:hidden];
  @apply [background:var(--johnbot-accent-soft)];
  @apply [color:var(--johnbot-accent-hover)];
  @apply [font-size:var(--johnbot-text-lg)];
  @apply [font-weight:var(--johnbot-weight-semibold)];
}

.profile-hero-avatar > img {
  @apply [width:100%];
  @apply [height:100%];
  @apply [object-fit:cover];
  @apply [outline:1px_solid_var(--johnbot-image-outline)];
  @apply [outline-offset:-1px];
  @apply [border-radius:inherit];
}

.profile-hero-text {
  @apply [min-width:0];
}

.profile-hero-text h3 {
  @apply [margin:0];
  @apply [overflow:hidden];
  @apply [text-overflow:ellipsis];
  @apply [white-space:nowrap];
  @apply [font-size:var(--johnbot-text-xl)];
  @apply [font-weight:var(--johnbot-weight-semibold)];
  @apply [color:var(--johnbot-text-primary)];
}

.profile-hero-text p {
  @apply [margin:0];
  @apply [overflow:hidden];
  @apply [text-overflow:ellipsis];
  @apply [white-space:nowrap];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [color:var(--johnbot-text-secondary)];
}

.profile-hero-actions {
  @apply [display:flex];
  @apply [flex:none];
  @apply [gap:var(--johnbot-space-2)];
  @apply [margin-inline-start:auto];
}

/* ─── Cards ─── */

/* The surface of a settings card (`.settings-modal-card`), for content that is not a row list. */
.profile-card {
  @apply [display:flex];
  @apply [flex-direction:column];
  @apply [gap:var(--johnbot-space-3)];
  @apply [margin:0];
  @apply [padding:var(--johnbot-space-4)];
  @apply [border-radius:var(--johnbot-radius-lg)];
  @apply [background:var(--johnbot-bg-surface)];
}

/* Lists of rows: the rows give the rhythm, as the rows of a settings card do. */
.profile-card.profile-facts,
.profile-card.profile-ranking,
.profile-card.profile-bars {
  @apply [row-gap:0];
  @apply [padding:var(--johnbot-space-1)_var(--johnbot-space-4)];
}

.profile-activity-placeholder {
  @apply [align-items:flex-start];
}

.profile-columns {
  @apply [display:grid];
  @apply [grid-template-columns:repeat(auto-fit,_minmax(300px,_1fr))];
  @apply [gap:var(--johnbot-space-4)];
  @apply [align-items:start];
}

.profile-columns > .ui-settings-section {
  @apply [height:100%];
  @apply [grid-template-rows:auto_1fr];
}

.profile-facts {
  @apply [display:flex];
  @apply [flex-direction:column];
  @apply [margin:0];
}

.profile-facts > div,
.profile-ranking li {
  @apply [display:flex];
  @apply [align-items:center];
  @apply [justify-content:space-between];
  @apply [gap:var(--johnbot-space-3)];
  @apply [min-height:calc(var(--johnbot-space-8)_+_var(--johnbot-space-3))];
  @apply [border-top:1px_solid_var(--johnbot-border)];
  @apply [font-size:var(--johnbot-text-sm)];
}

.profile-facts > div:first-child,
.profile-ranking li:first-child {
  @apply [border-top:0];
}

.profile-facts dt {
  @apply [flex:none];
  @apply [color:var(--johnbot-text-secondary)];
  @apply [transition:color_var(--johnbot-duration-normal)_var(--johnbot-ease-out)];
}

.profile-facts dd {
  @apply [display:flex];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-1-5)];
  @apply [min-width:0];
  @apply [margin:0];
  @apply [overflow:hidden];
  @apply [white-space:nowrap];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-weight:var(--johnbot-weight-medium)];
}

.profile-ranking {
  @apply [list-style:none];
}

.profile-ranking li {
  @apply [justify-content:flex-start];
  @apply [color:var(--johnbot-text-primary)];
  @apply [transition:opacity_var(--johnbot-duration-normal)_var(--johnbot-ease-out)];
}

.profile-ranking-avatar {
  @apply [width:var(--johnbot-space-6)];
  @apply [height:var(--johnbot-space-6)];
  @apply [flex:none];
}

.profile-ranking-name {
  @apply [flex:1];
  @apply [min-width:0];
  @apply [overflow:hidden];
  @apply [text-overflow:ellipsis];
  @apply [white-space:nowrap];
}

.profile-ranking strong,
.profile-bar-value {
  @apply [font-variant-numeric:tabular-nums];
  @apply [font-weight:var(--johnbot-weight-medium)];
}

/* ─── Bars ─── */

/*
 * The label column is as wide as the longest model name, up to a limit, so every bar starts at the
 * same place. A longer name ends with an ellipsis.
 */
.profile-bars {
  @apply [display:grid];
  @apply [grid-template-columns:fit-content(45%)_1fr_auto];
  @apply [column-gap:var(--johnbot-space-4)];
  @apply [margin:0];
  @apply [list-style:none];
}

.profile-bars li {
  @apply [display:grid];
  @apply [grid-column:1_/_-1];
  @apply [grid-template-columns:subgrid];
  @apply [align-items:center];
  @apply [min-height:calc(var(--johnbot-space-8)_+_var(--johnbot-space-1))];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [color:var(--johnbot-text-primary)];
  @apply [transition:opacity_var(--johnbot-duration-normal)_var(--johnbot-ease-out)];
}

.profile-bar-label {
  @apply [display:flex];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-1-5)];
  @apply [min-width:0];
  @apply [white-space:nowrap];
}

.profile-bar-name {
  @apply [overflow:hidden];
  @apply [text-overflow:ellipsis];
}

.profile-bar-track {
  @apply [height:var(--johnbot-space-2)];
  @apply [border-radius:var(--johnbot-radius-pill)];
  @apply [background:color-mix(in_srgb,_var(--johnbot-text-primary)_7%,_var(--johnbot-transparent))];
  @apply [overflow:hidden];
}

.profile-bar-fill {
  @apply [display:block];
  @apply [height:100%];
  @apply [border-radius:inherit];
}

.profile-bar-value {
  @apply [text-align:end];
  @apply [color:var(--johnbot-text-secondary)];
}

/* ─── Heatmap ─── */

.profile-heatmap {
