/* The Marketplace window: agents, apps and skills, and a page for each. Tokens only. */

/* ---------------------------------------------------------------- window */

/* A page of the window: the window card draws the surface, the line and the corner. */
.skills-marketplace {
  /* One inset for the whole window: the top bar title and the body start on it. */
  --marketplace-inset: var(--johnbot-space-6);
  @apply [display:grid];
  /* The side panel has the width of the settings page nav. The top row is above both columns. */
  @apply [grid-template-columns:max(var(--left-panel-width,_280px),_220px)_minmax(0,_1fr)];
  @apply [grid-template-rows:auto_minmax(0,_1fr)];
  @apply [width:100%];
  @apply [height:100%];
  @apply [overflow:hidden];
  @apply [color:var(--johnbot-text-primary)];
}

/* Menus and the connect and confirm dialogs open over the window. */
.marketplace-menu {
  @apply [z-index:calc(var(--johnbot-layer-dialog-host)_+_1)];
}

body:has(.skills-marketplace) :is(.integration-dialog-backdrop, .integration-wizard-dialog):not([data-nested]) {
  @apply [z-index:calc(var(--johnbot-layer-dialog-host)_+_1)];
}

.skills-marketplace-topbar {
  @apply [display:flex];
  @apply [align-items:center];
  @apply [justify-content:space-between];
  @apply [gap:var(--johnbot-space-3)];
  @apply [grid-column:1_/_-1];
  @apply [min-height:48px];
  @apply [padding:var(--johnbot-space-2)_var(--johnbot-space-2)_var(--johnbot-space-2)_var(--marketplace-inset)];
  @apply [border-bottom:1px_solid_var(--johnbot-border)];
}

/* ---------------------------------------------------------------- side panel */

/* As the settings page nav: the title and the kinds, then the apps that the user connected. */
.marketplace-nav {
  @apply [display:flex];
  @apply [grid-row:2];
  @apply [grid-column:1];
  @apply [min-width:0];
  @apply [min-height:0];
  @apply [flex-direction:column];
  @apply [gap:var(--johnbot-space-1)];
  @apply [overflow-y:auto];
  @apply [padding:var(--johnbot-space-4)_var(--johnbot-space-3)_var(--johnbot-space-3)];
  @apply [border-right:1px_solid_var(--johnbot-border)];
}

.marketplace-nav-title {
  @apply [margin:0_0_var(--johnbot-space-3)];
  @apply [padding:0_var(--johnbot-space-2)];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-lg)];
  @apply [font-weight:var(--johnbot-weight-semibold)];
  @apply [line-height:var(--johnbot-leading-lg)];
