  @apply [min-height:52px];
  @apply [padding:var(--johnbot-space-1-5)_var(--johnbot-space-2)];
  @apply [border-radius:var(--johnbot-radius-md)];
}

.marketplace-row-copy {
  @apply [display:grid];
  @apply [flex:1];
  @apply [gap:var(--johnbot-space-0-5)];
  @apply [min-width:0];
  @apply [overflow-wrap:anywhere];
}

/* ---------------------------------------------------------------- app list */

.marketplace-app-group {
  @apply [display:grid];
  @apply [gap:var(--johnbot-space-3)];
  @apply [padding-top:var(--johnbot-space-4)];
  @apply [border-top:1px_solid_var(--johnbot-border)];
}

.marketplace-app-group-title {
  @apply [display:flex];
  @apply [align-items:baseline];
  @apply [gap:var(--johnbot-space-2)];
  @apply [margin:0];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-lg)];
  @apply [font-weight:var(--johnbot-weight-semibold)];
}

.marketplace-app-group-count {
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-md)];
  @apply [font-weight:var(--johnbot-weight-regular)];
  @apply [font-variant-numeric:tabular-nums];
}

.marketplace-app-list {
  @apply [display:grid];
  @apply [grid-template-columns:repeat(auto-fill,_minmax(320px,_1fr))];
  @apply [column-gap:var(--johnbot-space-6)];
  @apply [row-gap:var(--johnbot-space-1)];
  @apply [margin:0];
  @apply [padding:0];
  @apply [list-style:none];
}

/* The row opens the app page; the status control sits above the hit area. */
.marketplace-app-row {
  @apply [position:relative];
  @apply [display:flex];
  @apply [min-width:0];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-3)];
  @apply [padding:var(--johnbot-space-2)];
  @apply [border-radius:var(--johnbot-radius-lg)];
}

@media (hover: hover) and (pointer: fine) {
  .marketplace-app-row:hover {
    @apply [background:var(--johnbot-bg-control-hover)];
  }

  /* The row hover has the color of the Connect button, so on a hovered row the button is one step lighter. */
  .marketplace-app-row:hover .marketplace-app-action[data-variant="secondary"]:not([data-disabled]) {
    @apply [background:var(--johnbot-bg-control-active)];
  }
}

.skills-marketplace .marketplace-app-row-hit {
  @apply [position:absolute];
  @apply [inset:0];
  @apply [width:100%];
  @apply [height:100%];
  @apply [padding:0];
  @apply [border-radius:inherit];
  @apply [background:transparent];
}

/* The row draws the hover. The shared ghost hover would cover the text above the hit area. */
.skills-marketplace .marketplace-app-row-hit:hover:not(:disabled) {
  @apply [background:transparent];
}

/* A little bigger than the settings tile, so that a logo with its own margin still reads. */
.marketplace-app-row > .integration-logo-tile {
  --integration-tile: 40px;
  @apply [pointer-events:none];
}

.marketplace-app-row-copy {
  @apply [display:grid];
  @apply [flex:1];
  @apply [min-width:0];
  @apply [gap:var(--johnbot-space-0-5)];
  @apply [pointer-events:none];
}

.marketplace-app-row-name {
  @apply [overflow:hidden];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-lg)];
  @apply [font-weight:var(--johnbot-weight-medium)];
  @apply [text-overflow:ellipsis];
  @apply [white-space:nowrap];
}

.marketplace-app-row-tagline {
  @apply [overflow:hidden];
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-md)];
  @apply [text-overflow:ellipsis];
  @apply [white-space:nowrap];
}

.marketplace-app-row-status {
  @apply [position:relative];
  @apply [display:inline-flex];
  @apply [flex:none];
}

/* As tall as a button, so the rows keep one height. The check has the success color; the word stays quiet. */
.marketplace-app-row-status > .marketplace-done {
  @apply [height:var(--johnbot-control-md)];
  @apply [gap:var(--johnbot-space-1-5)];
  @apply [padding-inline:var(--johnbot-space-2)];
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-md)];
  --marketplace-done-icon: var(--johnbot-icon-md);
  --marketplace-done-mark: var(--johnbot-success);
}

/* ---------------------------------------------------------------- pages */

.marketplace-page {
  @apply [display:grid];
  @apply [grid-template-columns:minmax(0,_1fr)_220px];
  @apply [gap:var(--johnbot-space-8)];
  @apply [align-items:start];
}

.marketplace-side {
  @apply [position:sticky];
  @apply [top:var(--johnbot-space-6)];
  @apply [padding-left:var(--johnbot-space-6)];
  @apply [border-left:1px_solid_var(--johnbot-border)];
}

/* `dt` and `dd` are direct children of the list, so each fact is one pair of grid rows. */
.marketplace-props {
  @apply [display:grid];
  @apply [gap:var(--johnbot-space-0-5)];
  @apply [margin:0];
}

.marketplace-props > dd {
  @apply [margin:0_0_var(--johnbot-space-3)];
}

.marketplace-props > dd:last-child {
  @apply [margin-bottom:0];
}

/* The Information list of an app page: the label and the value side by side. */
.marketplace-info {
  @apply [grid-template-columns:minmax(120px,_max-content)_minmax(0,_1fr)];
  @apply [column-gap:var(--johnbot-space-6)];
  @apply [row-gap:var(--johnbot-space-2)];
}

.marketplace-info > dd {
  @apply [margin:0];
}

.skills-marketplace .marketplace-link {
  @apply [height:auto];
  @apply [padding:0];
  /* The size of the other values in the list. */
  @apply [font-size:var(--johnbot-text-md)];
}

/* The skill-preview card, with room for more than one request. */
.marketplace-try {
  @apply [display:grid];
  @apply [gap:var(--johnbot-space-2)];
}

.skill-preview-card.marketplace-try-card {
  @apply [gap:var(--johnbot-space-2)];
}

/* Every text line is as tall as the chip, so the chip and the text share one line. */
.marketplace-try-card .skill-preview-request {
  @apply [width:min(100%,_560px)];
  @apply [line-height:var(--johnbot-space-6)];
}

.marketplace-try-card .skill-preview-chip {
  @apply [margin-inline-end:var(--johnbot-space-0-5)];
  @apply [vertical-align:top];
}

.marketplace-try-card .reference-chip-icon > :is(img, svg) {
  @apply [width:100%];
  @apply [height:100%];
}

/* The skill's SKILL.md, as the agent reads it. */
.marketplace-doc {
  @apply [min-width:0];
  @apply [padding:var(--johnbot-space-4)_var(--johnbot-space-6)];
  @apply [border:1px_solid_var(--johnbot-border)];
  @apply [border-radius:var(--johnbot-radius-card)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [overflow-wrap:anywhere];
}

.marketplace-doc > :first-child {
  @apply [margin-top:0];
}

.marketplace-doc > :last-child {
  @apply [margin-bottom:0];
}

/* ---------------------------------------------------------------- no results */

.marketplace-empty {
  @apply [display:grid];
  @apply [justify-items:center];
  @apply [gap:var(--johnbot-space-2)];
  @apply [padding:var(--johnbot-space-8)_var(--johnbot-space-6)];
  @apply [border:1px_dashed_var(--johnbot-border-strong)];
  @apply [border-radius:var(--johnbot-radius-card)];
  @apply [text-align:center];
}

.marketplace-empty > p {
  @apply [max-width:440px];
  @apply [margin:0];
}

.marketplace-empty > .ui-button {
  @apply [margin-top:var(--johnbot-space-2)];
}

.marketplace-empty-actions {
  @apply [display:flex];
  @apply [flex-wrap:wrap];
  @apply [justify-content:center];
  @apply [gap:var(--johnbot-space-2)];
}

/* ---------------------------------------------------------------- narrow */

/* A narrow window puts the kinds in a row above the list. The connected apps are in the list. */
@media (max-width: 720px) {
  .skills-marketplace {
    @apply [grid-template-columns:minmax(0,_1fr)];
    @apply [grid-template-rows:auto_auto_minmax(0,_1fr)];
  }

  .marketplace-nav {
    @apply [grid-row:2];
    @apply [overflow-x:auto];
    @apply [padding:var(--johnbot-space-2)_var(--johnbot-space-3)];
    @apply [border-right:0];
    @apply [border-bottom:1px_solid_var(--johnbot-border)];
  }

  .marketplace-nav-title,
  .marketplace-nav-group {
    @apply [display:none];
  }

  .marketplace-nav-list {
    @apply [grid-auto-columns:max-content];
    @apply [grid-auto-flow:column];
  }

  .skills-marketplace-body {
    @apply [grid-row:3];
    @apply [grid-column:1];
  }
}

@media (max-width: 860px) {
  .skills-marketplace {
    --marketplace-inset: var(--johnbot-space-4);
  }

  .marketplace-page {
    @apply [grid-template-columns:minmax(0,_1fr)];
  }

  .marketplace-side {
    @apply [position:static];
    @apply [padding:var(--johnbot-space-4)_0_0];
    @apply [border-top:1px_solid_var(--johnbot-border)];
    @apply [border-left:0];
  }

  .marketplace-head {
    @apply [flex-wrap:wrap];
  }
}

/* Last, because it is the most specific icon rule: every button icon in the window is 16px. */
.skills-marketplace .ui-button > svg,
.marketplace-search > svg {
  @apply [width:16px];
  @apply [height:16px];
}

/* After the icon size rule, so that the warning color wins. */
.marketplace-app-action[data-status="attention"] > svg {
  @apply [color:var(--johnbot-warning-text)];
}

/* === from: @johnbot/ui/features/settings/logo-color-picker.css === */
/* The logo color swatches, in the same shape as the agent avatar color grid. */
.logo-color-grid {
  @apply [display:grid];
  @apply [grid-template-columns:repeat(5,_32px)];
  @apply [min-width:0];
  @apply [margin:0];
  @apply [padding:0];
  @apply [border:0];
  @apply [gap:4px];
}

.logo-color-choice {
  @apply [display:grid];
  @apply [width:32px];
  @apply [height:32px];
  @apply [place-items:center];
  @apply [padding:0];
  @apply [border:1px_solid_transparent];
  @apply [border-radius:var(--johnbot-radius-md)];
  @apply [background:transparent];
  @apply [transition-property:scale,_background-color,_box-shadow];
  @apply [transition-duration:var(--johnbot-duration-normal),_var(--johnbot-duration-hover),_var(--johnbot-duration-hover)];
  @apply [transition-timing-function:ease-out];
}

.logo-color-choice:hover {
  @apply [background:var(--johnbot-hover)];
}

.logo-color-choice:active {
  @apply [scale:0.96];
}

.logo-color-choice-selected {
  @apply [background:var(--johnbot-border)];
  @apply [box-shadow:inset_0_0_0_1px_var(--johnbot-text-muted),_0_1px_3px_var(--johnbot-shadow-popover-ambient)];
}

.logo-color-swatch {
  @apply [display:block];
  @apply [width:18px];
  @apply [height:18px];
  @apply [border-radius:var(--johnbot-radius-pill)];
  @apply [box-shadow:inset_0_0_0_1px_var(--johnbot-border-strong)];
}

/* === from: @johnbot/ui/features/settings/sound-theme-picker.css === */
/* Sound feedback off, or on in one sound theme. Each card shows a moving dither tile. */
.sound-theme-picker {
  @apply [display:grid];
  @apply [grid-template-columns:repeat(auto-fill,_minmax(104px,_1fr))];
  @apply [width:100%];
  @apply [min-width:0];
  @apply [gap:var(--johnbot-space-2)];
}

.sound-theme-option {
  @apply [display:flex];
  @apply [min-width:0];
}

.sound-theme-card {
  @apply [display:flex];
  @apply [flex:1];
  @apply [flex-direction:column];
  @apply [min-width:0];
  @apply [padding:var(--johnbot-space-1)];
  @apply [border-radius:var(--johnbot-radius-lg)];
  @apply [background:var(--johnbot-bg-control)];
  @apply [box-shadow:inset_0_0_0_1px_var(--johnbot-border)];
  @apply [text-align:left];
  @apply [cursor:pointer];
  @apply [transition-property:scale,_background-color,_box-shadow];
  @apply [transition-duration:var(--johnbot-duration-normal),_var(--johnbot-duration-hover),_var(--johnbot-duration-normal)];
  @apply [transition-timing-function:var(--johnbot-ease-out)];
}

.sound-theme-card:hover {
  @apply [background:var(--johnbot-bg-control-hover)];
}

.sound-theme-card:active {
  @apply [scale:0.96];
}

.sound-theme-card[data-checked] {
  @apply [box-shadow:inset_0_0_0_1.5px_var(--johnbot-text-primary),_0_1px_3px_var(--johnbot-shadow-popover-ambient)];
}

.sound-theme-card[data-popped][data-checked] {
  @apply [animation:sound-theme-pop_var(--johnbot-duration-toast-enter)_var(--johnbot-ease-out)];
}

.sound-theme-option:has(:focus-visible) .sound-theme-card {
  @apply [box-shadow:var(--johnbot-focus-ring)];
}

/* The shader reads the ink from `color` and the back from `background-color`. Before it starts, or
   without WebGL, the same colors show as a dot screen. */
.sound-theme-dither {
  --sound-theme-ink: var(--johnbot-sound-off-ink);
  --sound-theme-back: var(--johnbot-sound-off-back);
  @apply [position:relative];
  @apply [height:56px];
  @apply [overflow:hidden];
  @apply [clip-path:inset(0_round_var(--johnbot-radius-md))];
  @apply [border-radius:var(--johnbot-radius-md)];
  @apply [color:var(--sound-theme-ink)];
  @apply [background-color:var(--sound-theme-back)];
  @apply [background-image:radial-gradient(var(--sound-theme-ink)_1px,_transparent_1.5px),_linear-gradient(135deg,_transparent,_var(--sound-theme-ink))];
  @apply [background-size:4px_4px,_100%_100%];
  @apply [opacity:0.72];
  @apply [filter:saturate(0.7)];
  @apply [transition-property:opacity,_filter];
  @apply [transition-duration:var(--johnbot-duration-overlay)];
  @apply [transition-timing-function:var(--johnbot-ease-out)];
}

.sound-theme-dither canvas {
  @apply [position:absolute];
  @apply [inset:0];
  @apply [width:100%];
  @apply [height:100%];
  @apply [pointer-events:none];
}

.sound-theme-card:hover .sound-theme-dither,
.sound-theme-card[data-checked] .sound-theme-dither {
  @apply [opacity:1];
  @apply [filter:none];
}

.sound-theme-dither[data-choice="default"] {
  --sound-theme-ink: var(--johnbot-sound-warm-ink);
  --sound-theme-back: var(--johnbot-sound-warm-back);
}

.sound-theme-dither[data-choice="mech"] {
  --sound-theme-ink: var(--johnbot-sound-mech-ink);
  --sound-theme-back: var(--johnbot-sound-mech-back);
}

.sound-theme-dither[data-choice="bubble"] {
  --sound-theme-ink: var(--johnbot-sound-bubble-ink);
  --sound-theme-back: var(--johnbot-sound-bubble-back);
}

.sound-theme-dither[data-choice="press"] {
  --sound-theme-ink: var(--johnbot-sound-press-ink);
  --sound-theme-back: var(--johnbot-sound-press-back);
}

.sound-theme-text {
  @apply [display:grid];
  @apply [min-width:0];
  @apply [padding:var(--johnbot-space-1-5)_var(--johnbot-space-1)_var(--johnbot-space-0-5)];
}

.sound-theme-name {
  @apply [overflow:hidden];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-md)];
  @apply [font-weight:var(--johnbot-weight-medium)];
  @apply [line-height:var(--johnbot-leading-md)];
  @apply [text-overflow:ellipsis];
  @apply [white-space:nowrap];
  @apply [cursor:inherit];
}

.sound-theme-hint {
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [line-height:var(--johnbot-leading-sm)];
}

@keyframes sound-theme-pop {
  0% {
    scale: 1;
  }

  35% {
    scale: 1.06;
    rotate: -1.5deg;
  }

  70% {
    scale: 0.98;
    rotate: 0.8deg;
  }

  100% {
    scale: 1;
    rotate: 0deg;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sound-theme-card[data-popped][data-checked] {
    @apply [animation:none];
  }

  .sound-theme-card:active {
    @apply [scale:1];
  }
}

/* === from: @johnbot/ui/features/settings/mcp-connect-dialog.css === */
/*
 * The content of the plugin connect dialogs. The frame is the shared connect dialog,
 * `WizardDialog` in `integration-layout.css`: the two logos, the title, and the buttons.
 */

/* One card of facts, its rows divided rather than spaced: a connection is one thing to read. */
.mcp-connect-card {
  @apply [display:flex];
  @apply [flex-direction:column];
  @apply [border-radius:var(--johnbot-radius-lg)];
  @apply [background:var(--johnbot-bg-grouped)];
}

.mcp-connect-row {
  @apply [position:relative];
  @apply [margin:0];
  @apply [padding:var(--johnbot-space-3)];
}

.mcp-connect-row + .mcp-connect-row {
  @apply [border-top:1px_solid_var(--johnbot-border-grouped)];
}

/* The steps that turn on a server another app runs. The heading leaves room for the setup link
   that sits in the row's corner. */
.mcp-local-heading {
  @apply [margin:0];
  @apply [padding-right:var(--johnbot-space-6)];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [font-weight:var(--johnbot-weight-semibold)];
  @apply [line-height:var(--johnbot-leading-sm)];
}

.mcp-local-steps {
  @apply [display:flex];
  @apply [flex-direction:column];
  @apply [gap:var(--johnbot-space-2)];
  @apply [margin:var(--johnbot-space-2)_0_0];
  @apply [padding-left:var(--johnbot-space-4)];
  @apply [list-style:decimal];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [line-height:var(--johnbot-leading-sm)];
}

.mcp-local-steps > li::marker {
  @apply [color:var(--johnbot-text-muted)];
}

.mcp-local-address {
  @apply [display:flex];
  @apply [align-items:baseline];
  @apply [justify-content:space-between];
  @apply [gap:var(--johnbot-space-3)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [line-height:var(--johnbot-leading-sm)];
}

.mcp-local-address > code {
  @apply [overflow-wrap:anywhere];
  @apply [color:var(--johnbot-text-primary)];
  @apply [font-family:var(--johnbot-font-mono)];
}

/* On the label's line, at the far end of it: the way out to the key page is a quiet aside, and it
   is the size of the other links in the marketplace rather than the size of the field. */
.mcp-connect-docs {
  @apply [position:absolute];
  @apply [top:var(--johnbot-space-3)];
  @apply [right:var(--johnbot-space-3)];
  @apply [gap:var(--johnbot-space-1-5)];
  @apply [color:var(--johnbot-text-muted)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [line-height:var(--johnbot-leading-sm)];
}

/* The mark that says the link leaves the app. It reads beside the words rather than over them,
   so it is the size of every other external-link mark in the marketplace. */
.mcp-connect-docs > svg {
  @apply [width:var(--johnbot-icon-sm)];
  @apply [height:var(--johnbot-icon-sm)];
  @apply [flex:0_0_auto];
  @apply [stroke-width:var(--johnbot-icon-stroke)];
}

.mcp-connect-privacy {
  @apply [display:flex];
  @apply [align-items:center];
  @apply [gap:var(--johnbot-space-2)];
  @apply [font-size:var(--johnbot-text-sm)];
  @apply [line-height:var(--johnbot-leading-sm)];
}

.mcp-connect-privacy svg {
  @apply [flex:none];
  @apply [width:var(--johnbot-icon-sm)];
  @apply [height:var(--johnbot-icon-sm)];
  @apply [color:var(--johnbot-text-muted)];
}

/* A joined server's sign-in page, drawn from the host's browser. The page keeps the shape of the host's frame. */
.mcp-sign-in-page {
  @apply [position:relative];
  @apply [width:100%];
  @apply [overflow:hidden];
  @apply [border:1px_solid_var(--johnbot-border)];
  @apply [border-radius:var(--johnbot-radius-lg)];
  @apply [background:var(--johnbot-bg-surface)];
}

.mcp-sign-in-page-note {
  @apply [min-width:0];
  @apply [margin:0];
}

/* A relayed sign-in: the page is in the user's own browser, so the dialog holds only the address field. */
.mcp-sign-in-relay-open {
  @apply [margin-top:var(--johnbot-space-4)];
}

.mcp-sign-in-relay-form {
  @apply [margin-top:var(--johnbot-space-4)];
}

/* In the connect dialog, the body's gap spaces them. The open button keeps the width of its words. */
.integration-wizard-body > :is(.mcp-sign-in-relay-open, .mcp-sign-in-relay-form) {
  @apply [margin-top:0];
}

.integration-wizard-body > .mcp-sign-in-relay-open {
  @apply [justify-self:start];
}

.mcp-sign-in-relay-row {
  @apply [display:flex];
  @apply [gap:var(--johnbot-space-2)];
}

.mcp-sign-in-relay-row > .ui-input {
  @apply [flex:1];
  @apply [min-width:0];
}

/* === from: ./features/provider-updates/provider-updates.css === */
/* The provider mark in the update notification's icon slot. The sizes match the slot the Toaster
   reserves for a status glyph, and the fill is the brand colour the provider row already uses, so
   the notification and the row that offers the same update read as one thing. */
.provider-update-toast-logo {
  @apply [width:var(--johnbot-icon-md)];
  @apply [height:var(--johnbot-icon-md)];
  @apply [overflow:visible];
  @apply [fill:var(--johnbot-provider-current)];
}

/* The action sits beside the words it acts on, centred on the title and the version line, rather than
   in a row of its own under them. The words stop at the button while it is there; a state with no
   button gives them the full width, so the running update's bar reaches the right edge. */
.provider-update-toast[data-sonner-toast][data-styled="true"] [data-action] {
  @apply [grid-row:1];
  @apply [align-self:center];
}

.provider-update-toast[data-sonner-toast][data-styled="true"]:has(.provider-update-toast-action:not([data-idle="true"]))
  [data-content] {
