@keyframes ui-plush-pop-in {
  from {
    opacity: 0;
    transform: scale(0.6);
  }
}

@keyframes ui-plush-breathe {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.012, 0.978);
  }
}

@keyframes ui-plush-blink {
  0%,
  93%,
  100% {
    transform: scaleY(1);
  }
  96% {
    transform: scaleY(0.1);
  }
}

@keyframes ui-plush-wink {
  0%,
  100% {
    transform: scaleY(1);
  }
  30%,
  60% {
    transform: scaleY(0.1);
  }
}

@keyframes ui-plush-squint {
  to {
    transform: translateY(-1.5%) scaleY(0.35);
  }
}

@keyframes ui-plush-look {
  0%,
  28%,
  86%,
  100% {
    transform: translate(0, 0);
  }
  34%,
  50% {
    transform: translate(calc(var(--ui-plush-look) * -1), calc(var(--ui-plush-look) * 0.2));
  }
  58%,
  78% {
    transform: translate(var(--ui-plush-look), calc(var(--ui-plush-look) * -0.3));
  }
}

@keyframes ui-plush-follow {
  0%,
  18% {
    transform: translate(calc(var(--ui-plush-look) * -0.9), calc(var(--ui-plush-look) * 0.6));
  }
  32% {
    transform: translate(0, calc(var(--ui-plush-look) * 0.6));
  }
  46%,
  70% {
    transform: translate(calc(var(--ui-plush-look) * 0.9), calc(var(--ui-plush-look) * 0.6));
  }
  100% {
    transform: translate(calc(var(--ui-plush-look) * -0.9), calc(var(--ui-plush-look) * 0.6));
  }
}

@keyframes ui-plush-ball-bounce {
  0%,
  60%,
  100% {
    transform: translateY(0) scale(1);
  }
  22% {
    transform: translateY(-110%) scale(0.95, 1.06);
  }
  42% {
    transform: translateY(0) scale(1.14, 0.84);
  }
  50% {
    transform: translateY(0) scale(1);
  }
}
